# Let me check if positions with 5s in output come from positions 
# with 5s in input + some shift

def find_pattern(input_grid, output_grid):
    h, w = len(input_grid), len(input_grid[0])

    # For each 5 in output, find its source in input
    for r_out in range(h):
        for c_out in range(w):
            if output_grid[r_out][c_out] == 5:
                print(f"Output 5 at ({r_out},{c_out})")
                # Check nearby positions in input
                for dr in range(-2, 3):
                    for dc in range(-2, 3):
                        r_in, c_in = r_out + dr, c_out + dc
                        if 0 <= r_in < h and 0 <= c_in < w:
                            if input_grid[r_in][c_in] == 5:
                                print(f"  -> Input 5 at ({r_in},{c_in})")

