# Let me check specific positions more carefully
# The transformation is something like: shift columns right, or shift rows down

def show_differences(in_grid, out_grid):
    h, w = len(in_grid), len(in_grid[0])
    for r in range(h):
        for c in range(w):
            if in_grid[r][c] != out_grid[r][c]:
                print(f"Diff at ({r},{c}): in={in_grid[r][c]}, out={out_grid[r][c]}")
    print()

show_differences(dp1_in, dp1_out)

# Let me check if ALL input positions (including 8s) shift down by 1 row
def check_down_shift(in_grid, out_grid):
    h, w = len(in_grid), len(in_grid[0])

    print("Input positions that DON'T match output down-shift:")
    for r in range(h):
        for c in range(w):
            # Check if in[r][c] appears at out[r+1][c] (if within bounds)
            if r + 1 < h:
                if in_grid[r][c] != out_grid[r+1][c]:
                    print(f"  ({r},{c}): {in_grid[r][c]} -> out[{r+1}][{c}] = {out_grid[r+1][c]}")

    print("\nChecking which input positions LEFT no trace (output at r+1 doesn't match):")
    left_behind = set()
    for r in range(h):
        for c in range(w):
            val = in_grid[r][c]
            if r + 1 < h and out_grid[r+1][c] != val:
                left_behind.add((r, c))
    print("Positions in input not seen in output down by 1:", sorted(left_behind))

    # Also check: for each position in output at row r, did we see matching in row r-1?
    print("\nOutput positions not explained by input upshelf:")
    for r in range(1, h):
        for c in range(w):
            val = out_grid[r][c]
            if in_grid[r-1][c] != val:
                print(f"  ({r},{c}): out={val}, but in[{r-1}][{c}] = {in_grid[r-1][c]}")

check_down_shift(dp1_in, dp1_out)

